const measurementName = "MEVAP";
const tag1Name = "MEVAP"
const tag2Name = "MEVAP2"
const tag3Name = "Temperature"

const fieldNames = [
    "T2_00", "T2_01", "T2_02", "T2_03",
    "T2_04", "T2_05", "T2_06"
];

// Optional scaling (example)
const scale = new Array(7).fill(0.0977);

// ---- Get Modbus Data ----
let data = msg.payload.data || msg.payload;

// ---- Build fields object ----
let fields = {};

for (let i = 0; i < Math.min(data.length, fieldNames.length); i++) {

    let raw = Number(data[i]);
    if (!Number.isFinite(raw)) continue;

    // Convert unsigned 16-bit → signed 16-bit
    if (raw > 32767) {
        raw = raw - 65536;
    }

    fields[fieldNames[i]] = raw * scale[i];
}

// ---- Build final payload ----
msg.payload = [{
    measurement: measurementName,
    tags: {
        System: tag1Name,
        Evaporator: tag2Name,
        Quantity: tag3Name
    },
    fields: fields
}];

return msg;

