const Vmax = 4.5;

const Pmin = -10;
const Pmax = 100;

// ---- Get Modbus Data ----
let modbusData = msg.payload || [];

// ---- Convert Modbus registers to signed 16-bit ----
modbusData = modbusData.map(v => (v > 32767 ? v - 65536 : v));

// ---- Convert register → Voltage ----
const multiplier = 1.245e-3;
let voltage = modbusData.map(v => v * multiplier);

// ---- Convert Voltage → Pressure (psi) ----
let psi = voltage.map(v =>
    Pmin + (v - Vmin) * (Pmax - Pmin) / (Vmax - Vmin)
);

// Optional conversion
let bar = psi.map(p => p * 0.06894574);

// ---- Build fields object ----
let fields = {};

enabledChannels.forEach((ch, index) => {

    if (ch >= psi.length) return;

    let raw = Number(psi[ch]);
    if (!Number.isFinite(raw)) return;

    let fieldName = fieldNames[index] || ("ch_" + index);

    fields[fieldName] = raw;
});

// ---- Build final payload ----
msg.payload = [{
    measurement: measurementName,
    tags: {
        System: tag1Name,
        Quantity: tag2Name
    },
    fields: fields
}];

return msg;

