];

// Channels to include (Modbus index positions)
const enabledChannels = [5];   // example


// ---- Get Modbus Data ----
let modbusData = msg.payload;

// Apply multiplier
const multiplier = 5.25e-6;
modbusData = modbusData.map(v => v * multiplier);


// ---- Convert mA → psi ----
const mflow_max = 1500; //
const mflow_min = 500; //

let mA = modbusData;

let mflow = mA.map(i =>
    (i - 0.004) * ((mflow_max - mflow_min) / 0.016) + mflow_min
);

// Optional conversion
let bar = mflow.map(p => 0.06894574 * p);


// ---- Build fields object ----
let fields = {};

enabledChannels.forEach((ch, index) => {

    if (ch >= mflow.length) return;

    let raw = Number(mflow[ch]);
    if (!Number.isFinite(raw)) return;

    let fieldName = fieldNames[index] || ("ch_" + index);

    fields[fieldName] = raw;

});


// ---- Build final payload ----
msg.payload = [{
    measurement: measurementName,
    tags: {
        System: tag1Name,
        Quantity: tag2Name
    },
    fields: fields
}];

return msg;

let T = msg.temperature;

let T_open = 10;

let state = flow.get("valve_state") || "INIT";

state = "CLOSED";
if (T > T_open) {
    state = "OPEN";
}

flow.set("valve_state", state);

msg.state = state;
return msg;

let data = msg.payload.data || msg.payload;

let raw = Number(data[4]);   // T_pump_in is index 0

if (Number.isFinite(raw)) {
    if (raw > 32767) {
        raw = raw - 65536;   // signed conversion
    }
    msg.temperature = raw * 0.0977;
} else {
    msg.temperature = null;
}

return msg;

let state = msg.state;

// DIOL logic:
// 0 = switch closed → current flows → valve OPEN
// 1 = switch open   → no current    → valve CLOSED

let value = (state === "OPEN") ? 0 : 1;

// Apply same command to 5 DO channels
msg.payload = {
    fc: 16,
    unitid: 1,
    address: 13000,
    quantity: 5,
    value: [1,1,1,1,1]
};

return msg;

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 13000,
    quantity: 5
};
return msg;

let state = msg.state;

// DIOL logic:
// 0 = switch closed → current flows → valve OPEN
// 1 = switch open   → no current    → valve CLOSED

let value = (state === "CLOSE") ? 0 : 1;

// Apply same command to 5 DO channels
msg.payload = {
    fc: 16,
    unitid: 1,
    address: 13000,
    quantity: 5,
    value: [value, value, value, value, value]
};

return msg;

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 13000,
    quantity: 3
};
return msg;

flow.set("setpoint_value", 0);
flow.set("setpoint_buffer", 0);
return null;

let val = flow.get("setpoint_buffer") || 0;
flow.set("setpoint_value", val);
return null;

// ---- Configuration ----
const measurementName = "Mistral";
const tag1Name = "CO2";
const tag2Name = "speed";

const fieldName = "Pump_speed";

let fields = {}

fields[fieldName] = flow.get("setpoint_value") || 0;

// ---- Build final payload ----
msg.payload = [{
    measurement: measurementName,
    tags: {
        System: tag1Name,
        Quantity: tag2Name
    },
    fields: fields
}];

return msg;
